#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int countTriplets(vector<int>& A) {
        unordered_map<int, int> cnt;
        for (int a : A)
            for (int b : A)
                cnt[a & b]++;

        int res = 0;
        for (int a : A)
            for (auto& [val, freq] : cnt)
                if ((a & val) == 0)
                    res += freq;

        return res;
    }
};
